 public function voidEvent(Request $q,int $id,int $eventId):Response{return $this->mutate($q,$id,function($u)use($q,$id,$eventId){$this->service->voidLatestEvent($id,$eventId,(int)($q->body['version']??0),(int)($q->body['event_version']??0),(string)($q->body['void_reason']??''),(int)$u['id'],$q->requestId);},'Latest status event voided and status recalculated.');}
 public function archive(Request $q,int $id,bool $restore):Response{return $this->mutate($q,$id,function($u)use($q,$id,$restore){$this->service->archive($id,(int)($q->body['version']??0),$restore,(int)$u['id'],$q->requestId);},$restore?'Prospect restored.':'Prospect archived.');}
 private function mutate(Request $q,int $id,callable $op,string $ok):Response{$u=$this->user();if($u instanceof Response)return $u;if(!$this->csrf->verify($q->body['_csrf']??null))return Response::html('Forbidden',403);try{$op($u);$this->flash->add('success',$ok);}catch(\DomainException|\InvalidArgumentException|\OutOfBoundsException|StaleRecordVersion $x){$this->flash->add('error',$x->getMessage());}return Response::redirect($this->router->url('prospects.show',['id'=>$id]));}
